// Some portions generated by Codex
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import org.eclipse.rdf4j.query.algebra.SingletonSet;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.query.explanation.QueryExplanationContext;
import org.junit.jupiter.api.Test;

class LmdbNativeParallelTelemetryTest {
	@Test
	void elasticBalancedInvocationsDoNotCreateWorkerSkew() {
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			var diagnostics = LmdbNativeParallelTelemetry.capture();
			var target = new SingletonSet();
			for (int i = 0; i < 9; i++)
				diagnostics.record(target, "Scan", 2,
						new long[] { 1, 1 }, new long[] { 11, 11 }, new long[] { 0, 0 }, new long[] { 10, 10 },
						new long[] { 1, 1 }, new boolean[] { true, true }, 0, true);
			diagnostics.record(target, "Scan", 8,
					new long[] { 1, 1, 1, 1, 1, 1, 1, 1 }, new long[] { 11, 11, 11, 11, 11, 11, 11, 11 },
					new long[8], new long[] { 10, 10, 10, 10, 10, 10, 10, 10 },
					new long[] { 1, 1, 1, 1, 1, 1, 1, 1 },
					new boolean[] { true, true, true, true, true, true, true, true }, 0, true);
			assertThat(diagnostics.get().stages()).singleElement().satisfies(stage -> {
				assertThat(stage.metrics().get("parallelRowSkewMaxToMean").value()).isEqualTo(1);
				assertThat(stage.metrics().get("parallelRowSkewMaxToMean").scope()).isEqualTo("maximum per invocation");
			});
		}
	}

	@Test
	void criticalPathUsesSpanRatherThanSumOrPairwiseOverlap() {
		var timing = LmdbNativeParallelTelemetry.timing(new long[] { 10, 20, 30 }, new long[] { 50, 80, 90 });
		assertThat(timing.wallNanos()).isEqualTo(80);
		assertThat(timing.activeNanos()).isEqualTo(160);
		assertThat(timing.tailNanos()).isEqualTo(10);
		assertThat(timing.minNanos()).isEqualTo(40);
		assertThat(timing.medianNanos()).isEqualTo(60);
		assertThat(timing.maxNanos()).isEqualTo(60);
		assertThat(timing.effectiveConcurrency()).isEqualTo(2);
	}

	@Test
	void missingWorkersAreNotPretendedToHaveCompleted() {
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			var diagnostics = LmdbNativeParallelTelemetry.capture();
			diagnostics.record(new SingletonSet(), "Scan", 2, new long[] { 10, 0 }, new long[] { 30, 0 },
					new long[] { 3, 0 }, new long[] { 7, 0 }, new long[] { 1, 0 }, new boolean[] { true, false }, 0,
					false);
			var snapshot = diagnostics.get();
			assertThat(snapshot.stages()).singleElement().satisfies(stage -> {
				assertThat(stage.status()).isEqualTo("PARTIAL");
				assertThat(stage.metrics().get("parallelWallNanos").count()).isEqualTo(20);
				assertThat(stage.metrics().get("parallelEffectiveConcurrency").value()).isEqualTo(1);
				assertThat(stage.metrics().get("parallelCpuNanos").count()).isNull();
			});
			assertThat(snapshot.workers()).hasSize(2).allSatisfy(worker -> assertThat(worker.complete()).isFalse());
			assertThat(snapshot.workers().get(0).waitNanos()).isEqualTo(3);
		}
	}

	@Test
	void repeatedInvocationsAccumulateOneStableStage() {
		try (var ignored = QueryExplanationContext.enter(Explanation.Level.Telemetry)) {
			var diagnostics = LmdbNativeParallelTelemetry.capture();
			var target = new SingletonSet();
			for (int i = 0; i < 3; i++)
				diagnostics.record(target, "Scan", 2,
						new long[] { 1, 1 }, new long[] { 11, 21 }, new long[] { 0, 0 }, new long[] { 2, 8 },
						new long[] { 1, 1 }, new boolean[] { true, true }, 2, true);
			var snapshot = diagnostics.get();
			assertThat(snapshot.stages()).singleElement().satisfies(stage -> {
				assertThat(stage.metrics().get("parallelInvocations").count()).isEqualTo(3);
				assertThat(stage.metrics().get("parallelWallNanos").count()).isEqualTo(60);
				assertThat(stage.metrics().get("parallelRowSkewMaxToMean").value()).isEqualTo(1.6);
			});
			assertThat(snapshot.workers()).hasSize(2);
			assertThat(snapshot.workers().get(1).rows()).isEqualTo(24);
		}
	}
}
